// Original educational content (English edition). Not ISACA text.
window.COBIT_CONTROLS_EN = window.COBIT_CONTROLS_EN || [];
window.COBIT_CONTROLS_EN.push(...
[
{"objective":"EDM01","purpose":"The IT governance system determines who makes technology decisions, under which principles and with what authority. Without a clear governance framework, IT investments, risks and resource use drift away from enterprise objectives and accountability weakens.","auditFocus":"The auditor focuses on whether the board and senior management have formally defined the principles, decision rights and committee structure for IT governance. The auditor also verifies that this structure operates in practice, i.e. that decisions are documented and that governance effectiveness is reviewed on a regular basis.","keyRisks":["IT decisions made by unauthorized individuals or by persons whose accountability is undefined","Governance structure remaining misaligned with enterprise strategy and regulatory expectations","Senior management becoming aware of IT-related issues late or incompletely"],"practices":[
{"code":"EDM01.01","name":"Evaluate the governance system.","title":"Assessing and designing the governance system","expectation":"The organization is expected to have documented its IT governance model (principles, decision rights, committee structure), taking into account stakeholder expectations and the internal and external context. The model is reassessed at intervals defined by the organization and upon major organizational, strategic or regulatory changes; the results are presented to the board or an authorized committee.","design":"Assess whether the governance model explicitly covers stakeholder requirements, risk appetite and decision rights, and whether an owner for the assessment and triggers for reassessment are defined.","operating":"List the governance assessments and trigger events within the audit period; verify through meeting minutes that an assessment was performed after significant changes and that the results were presented to the authorized body.","evidence":["Approved IT governance framework or governance policy","Decision rights matrix (RACI) and committee terms of reference","Most recent governance assessment report and stakeholder analysis","Board or committee minutes in which the assessment results were discussed"],"findings":["An IT governance framework exists but has not been updated following the most recent organizational restructuring, and new units are not included in the decision rights matrix.","No owner or frequency has been defined for assessing the governance model; the date of the most recent assessment cannot be determined."],"iso":["5.1","5.2"],"clauses":["4.1","4.2","5.1"],"itgc":""},
{"code":"EDM01.02","name":"Direct the governance system.","title":"Directing and implementing the governance structure","expectation":"Governance principles approved by senior management are expected to be communicated to the relevant managers, committee authorities and responsibilities are expected to be set out in formal terms of reference, and significant IT decisions are expected to be made through this structure. Changes to the governance structure are approved by the authorized body and communicated across the organization.","design":"Assess whether committee charters, delegation of authority rules and escalation paths are defined, and whether they are consistent with the approved governance principles.","operating":"Using risk-based selection from significant IT decisions made during the period, verify through minutes and approval records that each decision was made by the authorized committee or individual within the defined limits of authority.","evidence":["IT steering committee charter and membership list","Delegation of authority and signatory authority guideline","Committee meeting agendas, minutes and decision logs","Internal communication records evidencing that governance principles were communicated"],"findings":["The IT steering committee did not meet at the frequency required by its charter; some significant investment decisions were made outside the committee.","No follow-up owner or due date is assigned to committee decisions, so the implementation status of decisions cannot be tracked."],"iso":["5.2","5.4"],"clauses":["5.1","5.3"],"itgc":""},
{"code":"EDM01.03","name":"Monitor the governance system.","title":"Monitoring governance effectiveness","expectation":"The functioning of the governance system is expected to be monitored through indicators defined by the organization, internal audit results and independent assessments. Identified deviations are reported to the board, and improvement actions are tracked with assigned owners and due dates.","design":"Examine whether indicators, target values, reporting frequency and deviation thresholds have been defined to measure governance effectiveness.","operating":"List all governance reports required to be produced during the period; trace selected samples to confirm that reports were presented on time and that actions were opened and closed for identified deviations.","evidence":["Governance performance indicators and dashboard","Periodic IT governance reports presented to the board","Independent governance assessment or internal audit report","Improvement action tracking log"],"findings":["Governance indicators have been defined, but no target values have been set, so deviations cannot be identified.","Some improvement actions identified in the previous governance assessment remain open past their target dates."],"iso":[],"clauses":["9.1","9.3","10.1"],"itgc":""}
]},
{"objective":"EDM02","purpose":"IT spending creates value for the organization only when it delivers measurable business benefits. This objective provides assurance that the investment portfolio is selected in line with strategy and that expected benefits are tracked throughout the full life of each investment.","auditFocus":"The auditor focuses on whether the value and prioritization criteria used to approve IT investments are defined and whether they are applied consistently. The auditor also examines whether post-implementation benefit realization is measured and whether management takes decisions when deviations occur.","keyRisks":["Resources allocated to IT investments that are misaligned with strategy or deliver low returns","Failing investments continued because promised benefits are not measured","Portfolio decisions based on non-transparent or personal priorities"],"practices":[
{"code":"EDM02.01","name":"Establish the target investment mix.","title":"Defining the target balance of IT investments","expectation":"The organization is expected to define a target investment mix, approved by senior management, that classifies IT investments by purpose (such as running, growing or transforming the business) and by risk-return profile. This mix is reviewed in the budget cycle defined by the organization and upon changes in strategy.","design":"Assess whether the link between the target investment mix and strategy documents, the classification criteria and the approving authority are defined.","operating":"Obtain the complete population of investments approved during the period, calculate their distribution across the defined categories and compare it with the target mix; check that significant deviations were justified and approved.","evidence":["Approved IT strategy and investment policy","Portfolio document showing the target investment allocation","Minutes of the meeting at which the IT budget was approved","Investment portfolio list classified by category"],"findings":["No target investment mix has been defined; investment decisions are made solely on the basis of requests received from business units.","Although the actual investment allocation deviates significantly from the target mix, this has not been reported to management."],"iso":[],"clauses":[],"itgc":""},
{"code":"EDM02.02","name":"Evaluate value optimization.","title":"Assessing the IT portfolio from a value perspective","expectation":"Current and proposed IT investments, services and assets are expected to be evaluated comparatively against defined criteria covering strategic alignment, expected benefit, cost and risk. Evaluation results serve as input to portfolio decisions and are refreshed at intervals defined by the organization.","design":"Examine whether the evaluation criteria (business case template, scoring model) are objective, documented and capable of being applied consistently to all investments.","operating":"Using risk-based selection from investment proposals evaluated during the period, check that the business case was prepared in accordance with the template, that the scoring is verified by recalculation and that it is consistent with the decision made.","evidence":["Business case template and completed examples","Investment prioritization or scoring model","Portfolio review meeting minutes","Value-cost analysis of existing applications and services"],"findings":["Some investments were approved without a business case or with justifications that contain no benefit estimate.","Although a scoring model is defined, scores were not documented for some approved projects and the prioritization cannot be reproduced."],"iso":[],"clauses":[],"itgc":""},
{"code":"EDM02.03","name":"Direct value optimization.","title":"Setting direction for value management principles","expectation":"Senior management is expected to set the value management principles, benefit ownership and decision gates to be applied throughout the investment life cycle. For each significant investment, a business unit manager is assigned accountability for the benefits, and the criteria for continue, re-scope or stop decisions are defined.","design":"Assess whether the value management policy covers benefit ownership, stage gates and investment stop criteria.","operating":"For selected investments that passed through a stage gate during the period, verify through records that a benefit owner was assigned and that gate decisions were made by authorized individuals in accordance with the defined criteria.","evidence":["Value management or investment governance policy","Benefit owner assignment records per investment","Stage-gate decision forms","Decision records for investments that were stopped or re-scoped"],"findings":["No business-side benefit owner has been assigned to investments; benefit tracking is left solely to the IT function.","Although stage-gate criteria are defined, decisions to continue projects whose expected benefits had declined significantly were made without justification."],"iso":[],"clauses":[],"itgc":""},
{"code":"EDM02.04","name":"Monitor value optimization.","title":"Monitoring benefit realization","expectation":"The expected benefits of completed and ongoing investments are expected to be monitored by comparison with the measures defined in the business case. Post-implementation reviews are performed at times defined by the organization, and significant deviations are reported to management for corrective decisions.","design":"Examine whether benefit measures are defined in measurable terms in the business case and whether an owner and trigger for the post-implementation review process are specified.","operating":"Obtain the complete list of investments completed during the period; for selected investments, verify that a post-implementation review was performed, that realized benefits were calculated from source data and that deviations were reported.","evidence":["Post-implementation review reports","Benefit tracking sheet or portfolio dashboard","Value realization reports presented to management","Action decisions taken in response to deviations"],"findings":["No post-implementation review was performed for a significant portion of completed projects; whether the benefits were realized is unknown.","The data used in benefit reports was prepared without reconciliation to source systems, and some values cannot be verified."],"iso":[],"clauses":["9.1"],"itgc":""}
]},
{"objective":"EDM03","purpose":"Keeping IT-related risk within the organization's risk appetite is decisive for both business continuity and reputation. This objective ensures that IT risk is integrated into enterprise risk management and that senior management steers the risk profile through informed decisions.","auditFocus":"The auditor examines whether IT risk appetite and tolerance levels have been approved at board level and whether the risk management process operates in line with these levels. In particular, the auditor verifies with evidence that risks falling outside appetite are escalated and resolved in a timely manner.","keyRisks":["Arbitrary risk acceptance decisions because IT risk appetite is not defined","Significant IT risks not visible in enterprise risk reporting","Breaches of risk appetite not detected in time and not acted upon"],"practices":[
{"code":"EDM03.01","name":"Evaluate risk management.","title":"Assessing IT risk and risk appetite","expectation":"The organization is expected to regularly assess the impact of IT-related risks on business objectives and to define IT risk appetite and tolerance levels in alignment with enterprise risk appetite. The risk appetite statement is approved by the board or an authorized committee and revisited at intervals defined by the organization.","design":"Assess whether the risk appetite statement contains measurable thresholds, whether it is consistent with the enterprise risk framework and whether the approving authority is defined.","operating":"Inspect approval records for risk appetite reviews performed during the period; for selected significant IT risks in the risk register, verify through reassessment that they are correctly classified against the defined thresholds.","evidence":["Approved risk appetite and tolerance statement","Enterprise risk management policy and IT risk methodology","Periodic IT risk assessment report","Board or risk committee minutes approving the risk appetite"],"findings":["IT risk appetite is defined only in qualitative terms; there are no thresholds indicating which risk levels are acceptable.","The risk appetite statement has not been reassessed despite a significant change in the organization's digital transformation strategy."],"iso":[],"clauses":["6.1","8.2"],"itgc":""},
{"code":"EDM03.02","name":"Direct risk management.","title":"Directing risk management practices","expectation":"Senior management is expected to define roles and responsibilities for IT risk management, risk ownership, risk acceptance authorities and escalation rules. Risk acceptance decisions are made by individuals with authority appropriate to the risk level, with justification and for a defined period; risk awareness is supported through communication and awareness activities.","design":"Examine whether the risk acceptance authority matrix is tiered by risk level and whether escalation paths are clearly defined.","operating":"List all risk acceptance decisions made during the period; for samples selected on a risk basis, verify that each decision was made at the level required by the authority matrix, with justification and a stated validity period.","evidence":["Risk ownership and risk acceptance authority matrix","Risk acceptance forms and approval records","Risk escalation procedure","Communication and training records on risk awareness"],"findings":["Some high-level risks were accepted by managers at a lower level than required by the authority matrix.","Because no validity period is defined for risk acceptance decisions, open-ended acceptances exist that are never reassessed."],"iso":["5.4"],"clauses":["5.3","6.1","8.3"],"itgc":""},
{"code":"EDM03.03","name":"Monitor risk management.","title":"Monitoring the IT risk profile","expectation":"The IT risk profile is expected to be monitored through key risk indicators and the risk register, and its position relative to risk appetite is expected to be reported regularly to the board or the risk committee. Appetite breaches and significant risk events are handled through the defined escalation process, and actions are tracked until closure.","design":"Assess whether thresholds for key risk indicators, the reporting frequency and the course of action to be followed in the event of a breach are defined.","operating":"Inspect the risk reports and indicator data produced throughout the period; verify that an escalation and action record exists for every instance of a threshold breach.","evidence":["Key risk indicator (KRI) definitions and thresholds","Periodic IT risk reports presented to the risk committee","Current IT risk register","Escalation and action records for threshold breaches"],"findings":["Some key risk indicators exceeded their thresholds but were not reported to the risk committee.","The last assessment date of some risks in the risk register is outdated; risk levels do not reflect the current control environment."],"iso":[],"clauses":["8.2","9.1","9.3"],"itgc":""}
]},
{"objective":"EDM04","purpose":"Achieving IT objectives requires sufficient and competent human resources, budget, infrastructure and external service providers. This objective ensures that resources are planned according to strategic priorities and that the organization does not depend on a single individual or a single supplier for critical capabilities.","auditFocus":"The auditor examines whether resource needs are planned in connection with strategy and whether outsourcing decisions are made in accordance with defined principles. The auditor also verifies that resource utilization indicators are monitored and that critical capability gaps are reported to management.","keyRisks":["Key-person or single-supplier dependency in critical IT capabilities","Disruption of security and operational activities due to insufficient resources","Outsourcing decisions made without risk and cost analysis"],"practices":[
{"code":"EDM04.01","name":"Evaluate resource management.","title":"Assessing resource needs and sourcing options","expectation":"The organization is expected to assess its current and future IT resource needs (staff, competencies, budget, infrastructure) in relation to the strategic plan and to compare options such as insourcing, outsourcing or cloud against defined principles. The assessment is updated in planning cycles defined by the organization and upon significant changes in strategy.","design":"Examine whether the link between the resource planning process and strategic objectives, and the criteria for evaluating sourcing options (cost, risk, competency, dependency), are defined.","operating":"Inspect the resource plan and significant sourcing decisions within the period; for selected decisions, verify that alternatives were compared against defined criteria and approved by the authorized body.","evidence":["IT resource and capacity plan","Sourcing strategy","Analysis and approval documents supporting outsourcing decisions","Competency inventory or skills matrix"],"findings":["The resource plan contains only budget figures; competency needs and key-person dependency have not been assessed.","There is no record that alternatives and risks were assessed in the decision to outsource a significant service."],"iso":["5.19"],"clauses":["7.1","7.2"],"itgc":""},
{"code":"EDM04.02","name":"Direct resource management.","title":"Setting direction for resource management principles","expectation":"Senior management is expected to set principles for resource allocation, prioritization, competency development and the use of suppliers, and to assign responsibilities. Resource allocation decisions are made by authorized individuals in line with these principles; a backup and succession approach is defined for critical roles.","design":"Assess whether the resource management principles cover critical roles, backup staff, succession and supplier dependency.","operating":"Obtain the list of critical IT roles; for selected roles, verify that backup staff or a succession plan is actually in place and that resource allocation decisions are supported by approval records.","evidence":["Resource management principles or policy","Critical roles list and succession plans","Resource allocation and prioritization decision records","Competency development and training plans"],"findings":["Administration of a critical system depends on a single individual; there is no backup staff member or documented handover plan.","Resource prioritization decisions are made verbally between unit managers without going through a formal approval process."],"iso":["5.2"],"clauses":["5.3","7.1","7.2"],"itgc":""},
{"code":"EDM04.03","name":"Monitor resource management.","title":"Monitoring resource utilization and adequacy","expectation":"The utilization and capacity of IT resources and competency gaps are expected to be monitored through defined indicators, with the results reported to management. When resource shortages or idle resources are identified, corrective decisions are taken and tracked.","design":"Examine whether resource indicators (such as open positions, staff turnover rate, budget execution and capacity utilization) and their target values have been defined by the organization.","operating":"Inspect the resource reports for the period; verify selected indicator values by comparing them with data from source systems such as human resources and finance, and check that action was taken on identified gaps.","evidence":["Resource utilization indicators and periodic reports","IT budget execution reports","Open position and staff turnover data (personal data masked)","Action records relating to resource gaps"],"findings":["Although positions requiring critical competencies have remained open for an extended period, this has not been reported to management.","Budget execution data in the resource reports does not reconcile with the records in the finance system."],"iso":[],"clauses":["7.1","9.1"],"itgc":""}
]},
{"objective":"EDM05","purpose":"The board, regulators, customers and other stakeholders need accurate and timely information about IT performance and risks. This objective ensures that IT-related reporting is reliable and that stakeholder expectations are reflected in decision-making processes.","auditFocus":"The auditor examines whether stakeholders and reporting requirements have been identified and whether controls exist to ensure the accuracy and completeness of reports. The auditor also verifies that the effectiveness of reporting and communication is evaluated through stakeholder feedback.","keyRisks":["Incomplete or inaccurate IT information reported to the board or regulators","Significant stakeholders and their information needs not identified","Reporting obligations not met on time"],"practices":[
{"code":"EDM05.01","name":"Evaluate stakeholder engagement and reporting requirements.","title":"Identifying stakeholder and reporting requirements","expectation":"The organization is expected to document its internal and external IT-related stakeholders, their information needs and mandatory reporting obligations. The stakeholder map and the reporting inventory are updated at intervals defined by the organization and when new obligations arise.","design":"Examine whether the reporting inventory defines the audience, content, frequency, owner and source data for each report.","operating":"Test completeness by independently listing the mandatory and critical reports within the audit period and comparing them with the inventory; verify that inventory updates were made following trigger events.","evidence":["Stakeholder map or stakeholder analysis","IT reporting inventory","List of regulatory reporting obligations","Inventory update and approval records"],"findings":["Some IT reports submitted to the regulator are not included in the reporting inventory and have no defined owner.","The stakeholder analysis has not been updated for an extended period; new business units and critical external service providers are not covered."],"iso":["5.5","5.31"],"clauses":["4.2"],"itgc":""},
{"code":"EDM05.02","name":"Direct stakeholder engagement, communication and reporting.","title":"Directing stakeholder communication and reporting mechanisms","expectation":"Senior management is expected to define reporting and communication channels, approval steps and controls that safeguard information quality (such as reconciliation to source data and review independent of the preparer). Significant IT information communicated to external stakeholders is approved by authorized individuals before release.","design":"Assess whether the reporting procedure covers data sources, segregation between preparer and approver, and accuracy checks.","operating":"Using risk-based selection from critical reports prepared during the period, reperform the comparison with source data and verify that the approval records predate the release date.","evidence":["Communication and reporting policy or procedure","Report approval workflow records","Reconciliations of report data to source systems","External stakeholder communication plan"],"findings":["IT reports presented to the board are prepared and approved by the same person; no independent review is performed.","The calculation method for some indicators in the reports is not documented and cannot be reproduced from source data."],"iso":[],"clauses":["7.4","7.5"],"itgc":""},
{"code":"EDM05.03","name":"Monitor stakeholder engagement.","title":"Monitoring stakeholder engagement and communication effectiveness","expectation":"The extent to which stakeholders benefit from IT reporting and communication is expected to be evaluated through feedback, surveys or review meetings. Whether reports are delivered on time and accurately is monitored, and improvements are made to address identified shortcomings.","design":"Examine whether measures for reporting timeliness and accuracy, and a mechanism for collecting stakeholder feedback, are defined.","operating":"Compare the submission dates of mandatory reports for the period with their deadlines; verify through selected samples that improvement actions arising from stakeholder feedback were tracked.","evidence":["Stakeholder satisfaction survey results or feedback records","Report submission calendar and actual submission records","Correction records for reporting errors","Communication improvement action list"],"findings":["Some regulatory reports were submitted after the deadline and the cause of the delay was not analyzed.","Stakeholder feedback is collected, but no improvement actions have been raised because the results are not evaluated."],"iso":[],"clauses":["9.1","10.1"],"itgc":""}
]},
{"objective":"MEA01","purpose":"Performance that is not measured cannot be managed; a reliable monitoring system showing the extent to which IT processes and services achieve their objectives enables management to intervene in a timely manner. This objective provides assurance that performance and conformance data are consistently collected and reported and that deviations are corrected.","auditFocus":"The auditor examines whether performance indicators are linked to objectives and measurable, and whether reported data is consistent with source systems. The auditor also verifies that deviations from targets are converted into corrective actions and tracked through to closure.","keyRisks":["Decisions made on the basis of inaccurate or manipulable performance data","Deviations from targets going unnoticed or left without action","Indicators consisting solely of technical measurements unconnected to business objectives"],"practices":[
{"code":"MEA01.01","name":"Establish a monitoring approach.","title":"Establishing the monitoring approach","expectation":"The organization is expected to have a monitoring framework, agreed with stakeholders, that defines what is to be monitored for IT performance and conformance, by which method, at what frequency and by whom. The framework is aligned with the enterprise performance management approach and reviewed at intervals defined by the organization.","design":"Assess whether the scope of the monitoring framework defines indicator types, data sources and owners, and whether it covers critical processes and services.","operating":"List all monitoring activities defined in the framework; verify through records that selected activities were performed as defined throughout the period.","evidence":["Approved performance monitoring framework or procedure","Indicator catalog (definition, formula, data source, owner)","Framework review and approval records","Notes of meetings held with stakeholders on monitoring scope"],"findings":["The monitoring framework covers only infrastructure indicators; application and business process performance is not monitored.","The data source and owner of some indicators are not defined in the indicator catalog."],"iso":[],"clauses":["9.1"],"itgc":""},
{"code":"MEA01.02","name":"Set performance and conformance targets.","title":"Setting performance and conformance targets","expectation":"For each indicator, target and tolerance values based on business needs are expected to be set, approved by the relevant stakeholders and updated at intervals defined by the organization. Targets are consistent with service level agreements and compliance obligations.","design":"Examine whether targets are measurable, approved and consistent with service level agreements, and whether the approval required for changing targets is defined.","operating":"Inspect the approval records for selected targets in effect during the period; verify that all targets changed during the period were justified and approved by an authorized individual.","evidence":["Indicator list including target values","Service level agreements (SLAs) and operational level agreements","Target approval and revision records","Target-setting meeting minutes"],"findings":["Target values for some indicators were lowered without justification in periods when the targets were not met.","The service level committed in the SLA is inconsistent with internal performance targets."],"iso":[],"clauses":["6.2"],"itgc":""},
{"code":"MEA01.03","name":"Collect and process performance and conformance data.","title":"Collecting and processing performance and conformance data","expectation":"Performance data is expected to be collected from defined sources in a manner that is automated and traceable to the extent possible, and calculation rules are expected to be documented. Steps requiring manual intervention include accuracy checks and a change trail; data collection responsibilities are clearly assigned.","design":"Assess whether the data flow from source system to report is documented, whether manual steps are subject to controls and whether calculation rules are defined.","operating":"For indicators selected on a risk basis, verify the reported value by recalculating it from raw data extracted from the source system with read-only access; inspect the change trails in report files.","evidence":["Data flow diagram and indicator calculation rules","Raw data extracts from source systems","Indicator recalculation working papers","Access and change logs in the reporting tool"],"findings":["Indicators are calculated in manually maintained spreadsheets; there is no formula protection or change control.","Some recalculated indicator values differ from the reported values and the differences have not been explained."],"iso":["8.16"],"clauses":["7.5","9.1"],"itgc":""},
{"code":"MEA01.04","name":"Analyze and report performance.","title":"Analyzing and reporting performance","expectation":"Performance results are expected to be analyzed against targets, the reasons for deviations explained, and concise, holistic reports tailored to the audience presented at a frequency defined by the organization. Reports clearly show trends and significant deviations.","design":"Examine whether the report format includes a target-versus-actual comparison, trends and an explanation of deviations, and whether the management level to which reports are presented is defined.","operating":"List all reports required to be produced during the period; verify that selected reports were presented on time, that deviations were explained and that the reports were discussed at the relevant management meetings.","evidence":["Periodic IT performance reports or dashboards","Minutes of management meetings at which the reports were presented","Deviation analysis notes","Reporting calendar"],"findings":["No cause analysis was performed for off-target indicators in the performance reports; only numerical values were presented.","In some planned periods, a performance report was not prepared or was not presented to management."],"iso":[],"clauses":["9.1","9.3"],"itgc":""},
{"code":"MEA01.05","name":"Ensure the implementation of corrective actions.","title":"Driving corrective actions through to completion","expectation":"For significant performance and conformance deviations, corrective actions with a defined owner, target date and closure criterion are expected to be raised and tracked centrally until closure. The effectiveness of closed actions is verified and overdue actions are escalated.","design":"Assess whether the action tracking process includes steps for owner assignment, due dates, escalation and closure verification.","operating":"Obtain the complete list of actions opened and closed during the period; inspect the closure evidence for selected closed actions and verify that overdue actions were escalated.","evidence":["Corrective action tracking log","Action closure evidence","Escalation correspondence for overdue actions","Action status reports"],"findings":["Some actions are shown as closed without closure evidence.","Target dates of overdue actions have been repeatedly extended without authorized approval."],"iso":[],"clauses":["10.1","10.2"],"itgc":""}
]},
{"objective":"MEA02","purpose":"The internal control system is the fundamental safeguard for preventing, or detecting in a timely manner, errors, irregularities and security vulnerabilities in IT processes. This objective ensures that controls are continuously monitored, that management performs self-assessments and that control deficiencies are reported together with their root causes.","auditFocus":"The auditor examines whether the first and second lines regularly monitor controls and whether identified deficiencies are classified and escalated. The auditor also tests the reliability of management's self-assessment results through independent reperformance.","keyRisks":["Control deficiencies remaining undetected for extended periods","Self-assessments consisting merely of assertions unsupported by evidence","Recurrence of the same deficiencies because no root cause analysis is performed"],"practices":[
{"code":"MEA02.01","name":"Monitor internal controls.","title":"Monitoring the internal control environment","expectation":"The IT control framework (control inventory, risk and control matrix) is expected to be kept up to date, and the control environment is expected to be monitored through continuous monitoring, benchmarking and periodic reviews. Changes to the control framework are made in response to new risks and to process and system changes, and are approved.","design":"Assess whether the risk and control matrix covers critical processes and systems, and whether an owner, frequency and expected evidence are defined for each control.","operating":"List significant system and process changes within the period; verify that these changes were reflected in the risk and control matrix and that monitoring results were reported to management.","evidence":["Current IT risk and control matrix","Continuous control monitoring outputs or periodic monitoring reports","Control framework change and approval records","Internal control status reports"],"findings":["A critical application placed into production during the period was not added to the risk and control matrix.","In the control inventory, personnel who have left the organization are shown as the owners of some controls."],"iso":["5.35","5.36"],"clauses":["9.1"],"itgc":""},
{"code":"MEA02.02","name":"Review effectiveness of business process controls.","title":"Reviewing the effectiveness of business process controls","expectation":"The operation of automated and manual controls in business processes (including application controls) is expected to be reviewed through evidence generated by control owners and through independent testing. Assurance reports are obtained for controls delegated to external service providers, and the complementary controls that the organization must perform are evaluated.","design":"Examine whether the review program covers critical business processes and controls operated by external service providers, and whether testing methods are defined.","operating":"For controls selected on a risk basis from those reviewed during the period, re-inspect management's testing evidence; verify that service provider assurance reports cover the period and that exceptions noted in the reports were evaluated.","evidence":["Control review or test plan","Control testing working papers and supporting evidence","Service provider assurance reports (e.g. ISAE 3402 / SOC 1) and evaluation notes","Mapping of complementary user entity controls to the organization's controls"],"findings":["Exceptions and complementary user entity controls in the service provider assurance report have not been evaluated by the organization.","Some control tests rely solely on the control owner's assertion; no supporting evidence exists."],"iso":["5.22","5.36"],"clauses":["9.1"],"itgc":""},
{"code":"MEA02.03","name":"Perform control self-assessments.","title":"Performing control self-assessments","expectation":"Process owners are expected to assess the design and operation of their own controls at a frequency defined by the organization, using a defined methodology. Self-assessment results are supported by evidence and reviewed by the second line for reasonableness.","design":"Assess whether the self-assessment methodology includes assessment criteria, evidence expectations and a second-line review.","operating":"List all self-assessments completed during the period; for selected assessments, test the accuracy of the assertion by inspecting evidence for, or reperforming, controls rated “effective”.","evidence":["Control self-assessment methodology and questionnaire templates","Completed self-assessment forms and attached evidence","Second-line review notes","Self-assessment results report"],"findings":["In the self-assessments, all controls were marked “effective” without any evidence attached.","Some process owners did not complete the self-assessment in the planned period and this was not followed up."],"iso":["5.36"],"clauses":["9.1"],"itgc":""},
{"code":"MEA02.04","name":"Identify and report control deficiencies.","title":"Identifying and reporting control deficiencies","expectation":"Control deficiencies identified from all sources, such as self-assessments, internal and external audits and incidents, are expected to be consolidated in a central register, classified by severity and reported to the appropriate management level together with a root cause analysis. Significant deficiencies are communicated to senior management and, where necessary, to the audit committee in accordance with defined escalation rules.","design":"Examine whether deficiency classification criteria, root cause analysis expectations and escalation thresholds are defined.","operating":"Test the completeness of the register by reconciling deficiencies identified during the period to their sources; for selected significant deficiencies, verify the accuracy of the classification and the timeliness of escalation.","evidence":["Control deficiency register","Deficiency classification and escalation procedure","Root cause analysis records","Deficiency reports presented to the audit committee or senior management"],"findings":["Some control weaknesses identified in incident management records were not transferred to the deficiency register.","Because no root cause analysis was performed for recurring deficiencies, similar findings re-emerged in different periods."],"iso":["5.27","5.36"],"clauses":["9.3","10.2"],"itgc":""}
]},
{"objective":"MEA03","purpose":"The organization is subject to numerous legal, regulatory and contractual obligations in its IT activities; overlooking these obligations can lead to sanctions, breach of contract and reputational damage. This objective ensures that external requirements are systematically identified, reflected in internal policies and procedures, and that compliance is evidenced.","auditFocus":"The auditor examines whether external IT-related obligations are tracked in a current inventory and whether each obligation is mapped to an owner and to the control that addresses it. The auditor also evaluates whether compliance is verified with evidence and whether non-compliances are remediated in a timely manner.","keyRisks":["New or changed legal and contractual obligations going unnoticed","Policies and procedures failing to meet external requirements","Adverse outcomes in audits and inspections because compliance cannot be demonstrated"],"practices":[
{"code":"MEA03.01","name":"Identify external compliance requirements.","title":"Identifying external compliance requirements","expectation":"The organization is expected to identify, together with the legal and compliance functions, the legal, regulatory and contractual requirements affecting IT and to maintain them in an obligations inventory. Regulatory changes and new contracts are tracked through a defined monitoring mechanism, and the inventory is updated at intervals defined by the organization.","design":"Examine whether the obligations inventory includes sources, owners and a method for tracking changes, and whether it adequately covers IT-related obligations.","operating":"Independently list regulatory changes and significant new contracts within the period and compare them with the inventory; verify that updates were made within a reasonable time.","evidence":["Inventory of IT-related legal and regulatory obligations","Regulatory tracking records or notifications from the legal function","List of contractual obligations (such as data protection and service levels)","Inventory update records"],"findings":["The obligations inventory does not include a regulatory change that came into force during the period.","Information security obligations set out in customer contracts have not been transferred to the inventory."],"iso":["5.31","5.32","5.34"],"clauses":["4.2"],"itgc":""},
{"code":"MEA03.02","name":"Optimize response to external requirements.","title":"Translating external requirements into internal policies and procedures","expectation":"Identified external requirements are expected to be reflected in the relevant policies, standards and procedures, and each obligation is expected to be mapped to the control that addresses it and to an owner. When requirements change, the affected internal policies and procedures are identified and updated within a timeframe defined by the organization.","design":"Assess whether an obligation-to-control mapping exists and whether steps are defined to ensure that an impact analysis is performed when requirements change.","operating":"For selected requirements that changed during the period, inspect the impact analysis record; verify that the relevant policy or procedure was updated and that the update was approved and communicated.","evidence":["Obligation-policy-control mapping matrix","Impact analyses for requirement changes","Approval records for updated policies and procedures","Records showing that changes were communicated to relevant personnel"],"findings":["An impact analysis was performed for a new regulatory requirement, but the related procedures were not updated.","Some obligations are not mapped to any control or owner."],"iso":["5.1","5.31"],"clauses":["6.1"],"itgc":""},
{"code":"MEA03.03","name":"Confirm external compliance.","title":"Confirming compliance with external requirements","expectation":"The compliance function or process owners are expected to confirm, through regular checks, that policies, standards and procedures meet external requirements and that they are complied with in practice. Identified non-compliances are recorded, evaluated and remediated.","design":"Examine whether the scope and frequency of the compliance monitoring program have been defined by the organization and whether the program prioritizes high-risk obligations.","operating":"Test whether the compliance checks planned for the period were performed; for selected obligations, inspect evidence supporting compliance (such as data processing records and retention periods) using read-only access, and record it in the working papers with personal data masked.","evidence":["Compliance monitoring plan and checklists","Compliance check results reports","Non-compliance records and remediation plans","License compliance or data protection compliance assessments"],"findings":["Some obligations included in the compliance monitoring plan were not checked at all during the period.","No reconciliation was performed between the software licenses in use and the number of licenses purchased."],"iso":["5.32","5.34","5.36"],"clauses":["9.1"],"itgc":""},
{"code":"MEA03.04","name":"Obtain assurance of external compliance.","title":"Obtaining assurance over external compliance","expectation":"Assurance over compliance status is expected to be obtained through internal audit, independent assessments or certification audits, and the results reported to senior management. It is confirmed that corrective actions addressing non-compliances are completed in a timely and effective manner.","design":"Assess whether it is defined from which sources and at what frequency compliance assurance is to be obtained, and to whom the results are to be reported.","operating":"List the assurance reports for the period and the non-compliances arising from them; for selected non-compliances, verify that the corrective action was closed with evidence.","evidence":["Compliance assurance reports (internal audit, independent assessment, certification)","Compliance status reports presented to senior management","Corrective action tracking records","Regulatory inspection results and response correspondence"],"findings":["Some non-compliances identified in the previous certification audit were not closed by the target date.","Compliance status is reported to senior management only through summary assertions; the underlying assurance work is not referenced."],"iso":["5.35","5.36"],"clauses":["9.2","9.3","10.2"],"itgc":""}
]},
{"objective":"MEA04","purpose":"Independent and qualified assurance work provides the board and stakeholders with a reliable opinion that IT controls actually operate. This objective ensures that assurance activities are planned on a risk basis, performed in accordance with professional standards, and that recommendations are followed up.","auditFocus":"The auditor examines the independence and competence of the assurance function, whether the plan is based on a risk assessment and whether the working papers support the conclusions. The auditor also verifies that findings are reported and that recommendations are tracked through to closure.","keyRisks":["Assurance provided by teams whose independence is impaired or whose competence is insufficient","Assurance plan not covering high-risk IT areas","Recommendations arising from findings not implemented, leaving risks open"],"practices":[
{"code":"MEA04.01","name":"Ensure that assurance providers are independent and qualified.","title":"Independence and competence of assurance providers","expectation":"Internal or external teams performing assurance work are expected to be organizationally and individually independent of the unit under review and to possess the necessary IT audit competencies. Independence declarations are obtained before each engagement or at intervals defined by the organization; competency gaps are closed through training or specialist support.","design":"Examine whether the audit charter defines the reporting line and independence safeguards, and whether the competency framework defines the required areas of IT expertise.","operating":"List the assurance engagements performed during the period; for selected engagements, inspect team members' independence declarations, conflicts of interest arising from prior roles and the relevant competency records.","evidence":["Internal audit charter and organization chart","Engagement-level independence and conflict of interest declarations","Team competency matrix, certifications and training records","External assurance provider selection and independence assessment"],"findings":["A member of the audit team was assigned to the audit of an IT process for which they had recently been responsible.","Engagements in the cloud and cybersecurity areas were performed by teams with no documented competence in these areas."],"iso":["5.35"],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.02","name":"Develop risk-based planning of assurance initiatives.","title":"Risk-based planning of assurance activities","expectation":"The assurance plan is expected to be prepared taking into account the organization's risk assessment, strategic changes, prior findings and regulatory expectations, and to be approved by an authorized body such as the audit committee. The plan is updated at intervals defined by the organization and upon significant changes in risk.","design":"Assess whether the audit universe covers critical IT processes and systems and whether prioritization is based on a documented risk assessment.","operating":"Compare the approved plan with the audit universe and the risk assessment; verify that high-risk areas are included in the plan and that plan changes are justified and approved.","evidence":["Audit universe and risk assessment","Approved annual or multi-year assurance plan","Audit committee minutes on plan approval and changes","Plan completion report"],"findings":["Some IT areas with high risk scores have not been included in the plan for an extended period and the rationale is not documented.","There is no audit committee approval for engagements removed from the plan."],"iso":["5.35"],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.03","name":"Determine the objectives of the assurance initiative.","title":"Setting clear objectives for the assurance engagement","expectation":"For each assurance engagement, clear objectives showing which question the engagement seeks to answer are expected to be documented and agreed with the relevant stakeholders. Objectives are linked to the planning-stage risk assessment and approved before fieldwork begins.","design":"Examine whether the engagement planning template requires objectives to be linked to risks and approved by stakeholders.","operating":"For selected engagements completed during the period, verify through a comparison of dates and content that the objectives were documented and approved before fieldwork and that the final report addresses those objectives.","evidence":["Engagement planning memorandum","Opening meeting minutes and engagement letter","Approval record for the objectives","Planning-stage risk assessment"],"findings":["In some engagements, objectives were written after fieldwork had started and approval was obtained retrospectively.","Engagement objectives consist of general statements; it is unclear which risks fall within the scope of assurance."],"iso":[],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.04","name":"Define the scope of the assurance initiative.","title":"Defining the scope of the assurance engagement","expectation":"The engagement scope is expected to be defined on the basis of the objectives, clearly specifying the relevant processes, systems, locations, external service providers and review period, and to be agreed with stakeholders. Areas excluded from scope are documented with justification and disclosed in the report.","design":"Assess whether the scope definition includes period, system and process boundaries and the justification for scope exclusions.","operating":"For selected engagements, compare the defined scope with the areas actually tested; verify that scope changes were approved and disclosed in the report.","evidence":["Scope document or engagement letter","List of in-scope systems and processes","Scope change approval records","Scope and limitations section of the final report"],"findings":["The database layer of a critical application was excluded from scope without any stated justification.","The scope was narrowed during fieldwork, but this was not disclosed to readers of the report."],"iso":[],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.05","name":"Define the work program for the assurance initiative.","title":"Preparing the assurance work program","expectation":"A detailed work program setting out the test steps, evidence expectations, sampling approach and responsible person for each in-scope risk and control is expected to be prepared and approved by the audit manager. The program observes safe audit principles such as read-only access, making no changes in the production environment and protecting personal data.","design":"Examine whether the work program establishes the linkage between risks, controls and test steps, distinguishes between tests of design and tests of operating effectiveness, and includes a rationale for sampling.","operating":"For selected engagements, verify that the program was approved before fieldwork and that the working papers correspond to all program steps.","evidence":["Approved audit work program","Risk-control-test mapping","Sampling approach and rationale","Program approval and revision records"],"findings":["Test steps in the work program are not defined at control level; only general topic headings are included.","No working papers exist for some program steps and the reason they were not performed is not explained."],"iso":[],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.06","name":"Execute the assurance initiative, focusing on design effectiveness.","title":"Performing the assurance engagement: design effectiveness","expectation":"The auditor is expected to evaluate, through inquiry, document inspection and end-to-end tracing of a transaction (walkthrough), whether controls are designed to prevent or detect the related risk. Design weaknesses are identified before proceeding to operating effectiveness testing and are recorded with their rationale in the working papers.","design":"Examine whether the methodology defines criteria for design evaluation (risk-control alignment, control type, frequency, competence of the performer) and a documentation standard for walkthroughs.","operating":"Through quality review of selected working papers, verify that the walkthrough evidence includes end-to-end tracing of an actual transaction and that the design conclusion is supported by this evidence.","evidence":["Walkthrough working papers and process flowcharts","Interview notes","Design evaluation matrix","Quality review notes"],"findings":["The design evaluation relies solely on the policy document; how the control is actually performed was not traced.","Operating effectiveness testing was nonetheless performed for controls with identified design weaknesses, and the result was reported as “effective”."],"iso":[],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.07","name":"Execute the assurance initiative, focusing on operating effectiveness.","title":"Performing the assurance engagement: operating effectiveness","expectation":"The auditor is expected to test, through inspection, reperformance and observation of samples selected on a risk basis from a population whose completeness has been verified, that controls operated consistently throughout the review period. Identified exceptions are evaluated together with their causes and reflected in the conclusion.","design":"Examine whether the methodology includes guidance on population completeness verification, the rationale for sample selection and the evaluation of exceptions.","operating":"Through reperformance on selected working papers, verify how the population was obtained from the source system, that samples were selected from this population and that exceptions were correctly reflected in the conclusions.","evidence":["Population extracts and evidence of completeness verification","Sample selection records","Operating effectiveness testing working papers and supporting evidence (personal data masked)","Exception evaluation notes"],"findings":["Samples were selected from a list prepared manually by the auditee whose completeness had not been verified.","Exceptions identified during testing were treated as one-off occurrences and were not reflected in the conclusion."],"iso":[],"clauses":["9.2"],"itgc":""},
{"code":"MEA04.08","name":"Report and follow up on the assurance initiative.","title":"Reporting assurance results","expectation":"Findings are expected to be reported with supporting evidence, setting out the condition, criteria, cause and effect; management responses and action plans are expected to be included in the report and, where appropriate, an overall assurance opinion is expected to be provided. The report is distributed to the relevant management and the audit committee within a timeframe defined by the organization.","design":"Assess whether the reporting standard defines the finding structure, severity rating, the obtaining of management responses and the distribution list.","operating":"For selected reports issued during the period, verify that each finding is supported by working papers, that the ratings comply with the criteria and that the report was distributed to the authorized recipients on time.","evidence":["Issued assurance reports","Finding rating criteria","Management responses and action plans","Summary reports presented to the audit committee"],"findings":["The severity of some findings was rated lower than required under the rating criteria.","Some findings were issued without a management response and without an assigned owner."],"iso":[],"clauses":["9.2","9.3"],"itgc":""},
{"code":"MEA04.09","name":"Follow up on recommendations and actions.","title":"Tracking recommendations and actions through to closure","expectation":"Actions arising from assurance engagements are expected to be tracked in a central system, closures verified with evidence, and overdue actions reported to the audit committee. Where management chooses to accept the risk, this decision is made at an authorized level and documented.","design":"Examine whether the follow-up process defines the closure verification method, the escalation of overdue actions and the approval of risk acceptance.","operating":"Using risk-based selection from the complete list of actions closed during the period, independently inspect the closure evidence and, where necessary, retest the related control; verify that overdue actions were reported.","evidence":["Audit findings tracking system records","Closure evidence and verification notes","Follow-up reports presented to the audit committee","Risk acceptance approval forms"],"findings":["Some actions were closed solely on the basis of management's assertion; the assurance function did not verify closure.","High-risk findings whose target dates were repeatedly postponed were not reported to the audit committee."],"iso":[],"clauses":["10.1","10.2"],"itgc":""}
]}
]
);
